import React from 'react';

const Hero = () => {
  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section id="sprint" className="pt-20 pb-16 bg-gradient-to-br from-primary via-secondary to-accent">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center text-white">
          <div className="animate-fade-in">
            <h1 className="text-5xl md:text-7xl font-bold mb-6">
              Sprint <span className="text-yellow-300">Complete</span>
            </h1>
            <p className="text-xl md:text-2xl mb-8 max-w-3xl mx-auto">
              From <span className="font-semibold">Auditor</span> to <span className="font-semibold">Software Engineer</span>
              <br />Building software with <span className="font-semibold">Agile mindset</span>
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center items-center">
              <button 
                className="bg-accent text-white px-8 py-3 rounded-full font-semibold hover:bg-green-600 transition-colors duration-300"
                onClick={() => {
                  // Add download functionality here
                  console.log('Download CV clicked');
                }}
              >
                <i className="fas fa-download mr-2"></i>Download CV
              </button>
              <button 
                className="border-2 border-accent text-white px-8 py-3 rounded-full font-semibold hover:bg-accent hover:text-white transition-colors duration-300"
                onClick={() => scrollToSection('backlog')}
              >
                <i className="fas fa-play mr-2"></i>View Demo
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
